import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "assets/runescodex/creatures");
const files = readdirSync(dir)
  .filter((file) => /\.(gif|png|webp)$/i.test(file))
  .sort();

const lines = [
  "// Generated by scripts/generate-creature-images.mjs from apps/mobile/assets/runescodex/creatures.",
  "export const CREATURE_IMAGE_BY_KEY = {",
];

for (const file of files) {
  const key = file
    .toLowerCase()
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/[^a-z0-9]+/g, "");
  lines.push(
    `  ${JSON.stringify(key)}: require(${JSON.stringify(`../../assets/runescodex/creatures/${file}`)}),`,
  );
}

lines.push("};", "");
writeFileSync(join(root, "src/data/creature-images.js"), lines.join("\n"));
